import React from "react";
import { Link } from "react-router-dom";
import Moment from "react-moment";
import { FormattedMessage } from "react-intl";

const SettlementTable = ({ summaryPayload, getItemFunc, title, Error404Msg, summaryType, url }) => {
	console.log("PARAMS", summaryType, url);
	if (summaryPayload.length === 0) {
		// handles 404 error not found. Returns the error message set as the prop Error404Msg
		return (
			<tr>
				<td colSpan='3'>
					<p className='text-center text-danger'>
						<FormattedMessage id={Error404Msg} defaultMessage={Error404Msg} />
					</p>
				</td>
			</tr>
		);
	}

	return summaryPayload.map((item, index) => {
		return (
			<tr key={index + 1}>
				<td>
					<Moment format='ll'>{item["batchDate"]}</Moment>
				</td>
				{/* <td>{item['fileId']}</td> */}
				<td>
					{/* the summaryType in the url below is the dynamic prop from Summmary.js to automaticall link to the correct summary file be it postilion, flexcube or POSacquirers file. */}
					<Link to={`${url}${summaryType}/${item.batchDate}/1`}>
						{item["filename"] ? item["filename"] : "N/A"}
					</Link>
				</td>
				<td>
					<i
						className='fa fa-file text-center'
						fa-lg='true'
						title={title}
						style={{ color: "#262A2E", marginLeft: "10px", cursor: "pointer" }}
						onClick={getItemFunc(item.batchDate)}
					/>
				</td>
			</tr>
		);
	});
};

export default SettlementTable;
